svg.script:
// ============================================================
// MMA TILE ENGINE
//   D = A·B + C on 4×4 tiles
//   fp16 inputs (optional), fp32 accumulation
//   single SVG file, pure JS, no dependencies
// ============================================================

var $ = function(id){ return document.getElementById(id); };
var _f32 = new Float32Array(1);
var _i32 = new Int32Array(_f32.buffer);

function ESC(s){
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function FMT(v){
  if(!isFinite(v)) return v > 0 ? '\u221E' : (v < 0 ? '-\u221E' : 'NaN');
  if(Math.abs(v) >= 10000) return v.toExponential(1);
  return String(Math.round(v*1000)/1000);
}
function label(x, y, txt, fs, color, anchor){
  return '<text x="'+x+'" y="'+y+'" font-size="'+fs+'" fill="'+color+
         '" text-anchor="'+(anchor||'middle')+'" font-family="Courier New, monospace" pointer-events="none">'+
         ESC(txt)+'</text>';
}

// ---- FP16 emulation (round to nearest, flush subnormals) ----
function fp16(x){
  _f32[0] = x;
  var i = _i32[0];
  var s = i & 0x80000000;
  var e = (i >>> 23) & 0xff;
  var m = i & 0x7fffff;
  if(e === 0xff) return x;
  var ne = e - 112;
  if(ne >= 31){ _i32[0] = s | 0x7f800000; return _f32[0]; }
  if(ne <= 0) return s ? -0 : 0;
  var m2 = (m + 0x1000) >>> 13;
  if(m2 >= 0x400){
    m2 = 0; ne++;
    if(ne >= 31){ _i32[0] = s | 0x7f800000; return _f32[0]; }
  }
  _i32[0] = s | ((ne+112) << 23) | (m2 << 13);
  return _f32[0];
}
function f32(x){ _f32[0] = x; return _f32[0]; }

// ---- state ----
var M = 4, K = 4, N = 4;
var T = 4;
var FP16 = false;
var A, B, C;
var refMaxAbs = 1;
var accum = null;
var curOp = null;
var cursor = { ti:0, tj:0, tk:0, running:false, done:false, t:0, speed:0.5 };
var preset = 's4';
var sel = null, editBuf = null, freshEdit = true;
var dirty = true, hudDirty = true;

// ---- matrix allocation helpers ----
function alloc(m, n, f){
  var a = [];
  for(var i = 0; i < m; i++){
    a[i] = [];
    for(var j = 0; j < n; j++) a[i][j] = f ? f(i,j) : 0;
  }
  return a;
}
function clone2D(X){
  var a = [];
  for(var i = 0; i < X.length; i++) a[i] = X[i].slice();
  return a;
}
function loadTile(X, r, c){
  var t = [];
  for(var i = 0; i < T; i++){
    t[i] = [];
    for(var j = 0; j < T; j++){
      t[i][j] = (X[r+i] !== undefined && X[r+i][c+j] !== undefined) ? X[r+i][c+j] : 0;
    }
  }
  return t;
}
function storeTile(X, r, c, t){
  for(var i = 0; i < T; i++)
    for(var j = 0; j < T; j++)
      if(X[r+i]) X[r+i][c+j] = t[i][j];
}

// ---- THE PRIMITIVE: D = A·B + C on one 4×4 tile ----
function mmaTile(at, bt, ct, dt){
  for(var i = 0; i < T; i++){
    for(var j = 0; j < T; j++){
      var s = ct[i][j];
      for(var k = 0; k < T; k++){
        var a = at[i][k], b = bt[k][j];
        if(FP16){
          a = fp16(a); b = fp16(b);
          s = f32(s + a*b);
        } else {
          s = s + a*b;
        }
      }
      dt[i][j] = s;
    }
  }
}

// ---- full reference compute (for static view + reference scale) ----
function computeC(){
  C = alloc(M, N, function(){ return 0; });
  for(var ti = 0; ti < M; ti += T){
    for(var tj = 0; tj < N; tj += T){
      var acc = alloc(T, T, function(){ return 0; });
      for(var tk = 0; tk < K; tk += T){
        var at = loadTile(A, ti, tk);
        var bt = loadTile(B, tk, tj);
        mmaTile(at, bt, acc, acc);
      }
      storeTile(C, ti, tj, acc);
    }
  }
  // Update reference max so the 3D view has a stable colour/height scale
  var m = 0;
  for(var i = 0; i < M; i++) for(var j = 0; j < N; j++){
    var v = Math.abs(C[i][j]);
    if(v > m) m = v;
  }
  refMaxAbs = m < 0.01 ? 1 : m;
}

// ---- setup / presets ----
function setSize(m, k, n, p){
  M = m; K = k; N = n; preset = p;
  A = alloc(M, K, function(i,j){ return i===j ? 1 : 0; });
  B = alloc(K, N, function(i,j){ return i===j ? 1 : 0; });
  resetAnim();
  computeC();
  // Reset 3D camera distance to fit the new matrix
  if(typeof V3 !== 'undefined'){ V3.dist = v3_defaultDist(); }
  dirty = true; hudDirty = true;
}
function randomize(){
  for(var i = 0; i < M; i++) for(var k = 0; k < K; k++) A[i][k] = Math.floor(Math.random()*19)-9;
  for(var k2 = 0; k2 < K; k2++) for(var j = 0; j < N; j++) B[k2][j] = Math.floor(Math.random()*19)-9;
  resetAnim(); computeC();
  dirty = true; hudDirty = true;
}
function identity(){
  for(var i = 0; i < M; i++) for(var k = 0; k < K; k++) A[i][k] = (i===k)?1:0;
  for(var k2 = 0; k2 < K; k2++) for(var j = 0; j < N; j++) B[k2][j] = (k2===j)?1:0;
  resetAnim(); computeC();
  dirty = true; hudDirty = true;
}

// ---- animation cursor ----
function resetAnim(){
  cursor.ti = 0; cursor.tj = 0; cursor.tk = 0;
  cursor.running = false; cursor.done = false; cursor.t = 0;
  accum = null; curOp = null;
  C = alloc(M, N, function(){ return 0; });
}

function step(){
  if(cursor.done) return;
  var ti = cursor.ti, tj = cursor.tj, tk = cursor.tk;

  var at = loadTile(A, ti*T, tk*T);
  var bt = loadTile(B, tk*T, tj*T);
  if(!accum) accum = alloc(T, T, function(){ return 0; });

  var before = clone2D(accum);
  mmaTile(at, bt, accum, accum);
  var after = clone2D(accum);

  curOp = { ti: ti, tj: tj, tk: tk, at: at, bt: bt, before: before, after: after };

  cursor.tk++;
  if(cursor.tk * T >= K){
    storeTile(C, ti*T, tj*T, accum);
    accum = null;
    cursor.tk = 0;
    cursor.tj++;
    if(cursor.tj * T >= N){
      cursor.tj = 0;
      cursor.ti++;
      if(cursor.ti * T >= M){
        cursor.done = true;
        cursor.running = false;
      }
    }
  }
  dirty = true; hudDirty = true;
}

function togglePlay(){
  if(cursor.done) resetAnim();
  if(!cursor.running && !curOp){
    C = alloc(M, N, function(){ return 0; });
    accum = null;
  }
  cursor.running = !cursor.running;
  cursor.t = 0;
  dirty = true; hudDirty = true;
}

function stepOnce(){
  if(cursor.done) return;
  if(!curOp){
    C = alloc(M, N, function(){ return 0; });
    accum = null;
  }
  cursor.running = false;
  step();
}

// ---- layout ----
function layout(){
  var maxDim = Math.max(M, K, N);
  var STEP = Math.min(52, Math.floor(440 / maxDim));
  STEP = Math.max(STEP, 20);

  var aW = K*STEP, aH = M*STEP;
  var bW = N*STEP, bH = K*STEP;
  var cW = N*STEP, cH = M*STEP;
  var opW = 70;
  var totalW = aW + opW + bW + opW + cW;
  var maxH = Math.max(aH, bH, cH);
  var startX = (1920 - totalW) / 2;
  var startY = 210;

  return {
    STEP: STEP,
    ax: startX,                 ay: startY + (maxH-aH)/2,
    bx: startX + aW + opW,      by: startY + (maxH-bH)/2,
    cx: startX + aW + opW + bW + opW, cy: startY + (maxH-cH)/2,
    aw: aW, ah: aH, bw: bW, bh: bH, cw: cW, ch: cH,
    mulX: startX + aW + opW/2,
    eqX:  startX + aW + opW + bW + opW/2,
    mulY: startY + maxH/2,
    eqY:  startY + maxH/2,
    bottom: startY + maxH
  };
}

// ---- drawing ----
function brackets(x, y, w, h, color){
  var pad = 12, ext = 10;
  return '<path d="M '+(x-pad)+' '+(y-ext)+' L '+(x-pad-8)+' '+(y-ext)+
         ' L '+(x-pad-8)+' '+(y+h+ext)+' L '+(x-pad)+' '+(y+h+ext)+
         '" fill="none" stroke="'+color+'" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" pointer-events="none"/>'+
         '<path d="M '+(x+w+pad)+' '+(y-ext)+' L '+(x+w+pad+8)+' '+(y-ext)+
         ' L '+(x+w+pad+8)+' '+(y+h+ext)+' L '+(x+w+pad)+' '+(y+h+ext)+
         '" fill="none" stroke="'+color+'" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" pointer-events="none"/>';
}

function drawMatrixCells(X, x, y, rows, cols, STEP, color, name){
  var s = '';
  var fs = Math.max(11, Math.floor(STEP * 0.42));
  var editable = (name === 'A' || name === 'B') && !cursor.running && !cursor.done;

  for(var i = 0; i < rows; i++){
    for(var j = 0; j < cols; j++){
      var cx = x + j*STEP, cy = y + i*STEP;
      var active = sel && sel.m === name && sel.i === i && sel.j === j;
      var stroke = active ? '#ffffff' : color;
      var sw = active ? 2.5 : 0.6;
      var fill = active ? '#0d2a18' : 'none';
      var attrs = '';
      if(editable){
        attrs = ' data-m="'+name+'" data-i="'+i+'" data-j="'+j+'" style="cursor:pointer"';
      }
      s += '<rect x="'+cx+'" y="'+cy+'" width="'+STEP+'" height="'+STEP+
           '" fill="'+fill+'" stroke="'+stroke+'" stroke-width="'+sw+
           '" stroke-opacity="'+(active?1:0.6)+'"'+attrs+'/>';
      var txt;
      if(active && editBuf !== null) txt = editBuf;
      else txt = FMT(X[i] ? X[i][j] : 0);
      s += label(cx + STEP/2, cy + STEP/2 + fs*0.36, txt, fs, active ? '#ffffff' : color, 'middle');
    }
  }
  for(var ti = T; ti < rows; ti += T){
    s += '<line x1="'+x+'" y1="'+(y+ti*STEP)+'" x2="'+(x+cols*STEP)+'" y2="'+(y+ti*STEP)+
         '" stroke="'+color+'" stroke-width="1.8" stroke-opacity="0.85" pointer-events="none"/>';
  }
  for(var tj = T; tj < cols; tj += T){
    s += '<line x1="'+(x+tj*STEP)+'" y1="'+y+'" x2="'+(x+tj*STEP)+'" y2="'+(y+rows*STEP)+
         '" stroke="'+color+'" stroke-width="1.8" stroke-opacity="0.85" pointer-events="none"/>';
  }
  return s;
}

function hlTile(x, y, STEP, ti, tj, color){
  return '<rect x="'+(x+tj*T*STEP)+'" y="'+(y+ti*T*STEP)+
         '" width="'+(T*STEP)+'" height="'+(T*STEP)+
         '" fill="none" stroke="'+color+'" stroke-width="3.5" pointer-events="none"/>';
}

function drawMiniGrid(X, x, y, step, color){
  var s = '';
  var fs = Math.max(9, Math.floor(step * 0.42));
  for(var i = 0; i < T; i++){
    for(var j = 0; j < T; j++){
      var cx = x + j*step, cy = y + i*step;
      s += '<rect x="'+cx+'" y="'+cy+'" width="'+step+'" height="'+step+
           '" fill="none" stroke="'+color+'" stroke-width="1.2" stroke-opacity="0.75" pointer-events="none"/>';
      var v = X[i] ? X[i][j] : 0;
      s += label(cx + step/2, cy + step/2 + fs*0.36, FMT(v), fs, color, 'middle');
    }
  }
  return s;
}

// ---- workbench ----
function drawWorkbench(y){
  var h = 1080 - y - 40;
  var s = '';
  s += '<rect x="40" y="'+y+'" width="1840" height="'+h+
       '" fill="#010801" stroke="#1f7a3d" stroke-width="2" pointer-events="none"/>';
  s += label(60, y+28, '// WORKBENCH  \u2014  TILE PRIMITIVE  D = A_tile \u00B7 B_tile + C_acc',
             16, '#1f7a3d', 'start');

  if(!curOp){
    s += label(960, y + h/2, 'PRESS  PLAY  OR  STEP  TO EXECUTE THE TILE LOOP',
               22, '#1f7a3d', 'middle');
    return s;
  }

  var lx = 80, ly = y + 66;
  s += label(lx, ly, '// TILE CURSOR', 13, '#1f7a3d', 'start');
  s += label(lx, ly+28, 'ti = '+curOp.ti+'   (row tile of C)', 17, '#4fc3ff', 'start');
  s += label(lx, ly+52, 'tj = '+curOp.tj+'   (col tile of C)', 17, '#4fc3ff', 'start');
  s += label(lx, ly+76, 'tk = '+curOp.tk+'   (K tile)', 17, '#4fc3ff', 'start');
  s += label(lx, ly+112, 'A rows '+(curOp.ti*T)+'-'+(curOp.ti*T+T-1)+
              ', cols '+(curOp.tk*T)+'-'+(curOp.tk*T+T-1), 13, '#39ff6e', 'start');
  s += label(lx, ly+132, 'B rows '+(curOp.tk*T)+'-'+(curOp.tk*T+T-1)+
              ', cols '+(curOp.tj*T)+'-'+(curOp.tj*T+T-1), 13, '#ffd23f', 'start');
  s += label(lx, ly+164, FP16 ? 'fp16 in / fp32 accum' : 'fp32 in / fp32 accum',
             13, '#1f7a3d', 'start');

  var tstep = 28, tw = T*tstep;
  var gx = 460, gy = y + 66;

  var gxs = [
    { x: gx,                  X: curOp.at,     col: '#39ff6e', t: 'A_tile' },
    { x: gx + (tw+70),        X: curOp.bt,     col: '#ffd23f', t: 'B_tile' },
    { x: gx + (tw+70)*2,      X: curOp.before, col: '#4fc3ff', t: 'C_acc' },
    { x: gx + (tw+70)*3,      X: curOp.after,  col: '#ffffff', t: 'C_acc\'' }
  ];
  for(var i = 0; i < gxs.length; i++){
    var g = gxs[i];
    s += label(g.x, gy - 8, g.t, 13, g.col, 'start');
    s += drawMiniGrid(g.X, g.x, gy, tstep, g.col);
  }
  var my = gy + tw/2;
  s += label(gx + tw + 35,             my, '\u00D7', 30, '#1f7a3d');
  s += label(gx + (tw+70) + tw + 35,   my, '+',     30, '#1f7a3d');
  s += label(gx + (tw+70)*2 + tw + 35, my, '\u2192', 30, '#1f7a3d');

  var nx = gx + (tw+70)*3 + tw + 60, ny = y + 66;
  s += label(nx, ny,      '// PRIMITIVE', 13, '#1f7a3d', 'start');
  s += label(nx, ny+26,   'D = A\u00B7B + C  on one tile', 15, '#b6ffd0', 'start');
  s += label(nx, ny+52,   '4\u00D74 tile, 16 parallel MACs', 13, '#1f7a3d', 'start');
  s += label(nx, ny+78,   'inputs rounded to 10 mantissa bits', 13, '#1f7a3d', 'start');
  s += label(nx, ny+96,   'accumulator held in fp32', 13, '#1f7a3d', 'start');
  s += label(nx, ny+122,  'stored to C when tk completes', 13, '#1f7a3d', 'start');
  s += label(nx, ny+148,  'single-threaded model:', 13, '#1f7a3d', 'start');
  s += label(nx, ny+166,  'models dataflow, not parallelism', 13, '#1f7a3d', 'start');

  var laneY = y + 210;
  if(laneY > y + h - 80) laneY = y + h - 80;
  var i0 = 0, j0 = 0;
  s += label(80, laneY, 'LANE ('+i0+','+j0+') OF TILE  \u2014  scalar reduction:', 14, '#1f7a3d', 'start');
  var terms = [];
  for(var k = 0; k < T; k++) terms.push(FMT(curOp.at[i0][k]) + '\u00B7' + FMT(curOp.bt[k][j0]));
  s += label(80, laneY+26, '  '+terms.join('  +  '), 17, '#b6ffd0', 'start');
  var b0 = curOp.before[i0][j0];
  var a0 = curOp.after[i0][j0];
  s += label(80, laneY+52,
             '  acc = '+FMT(b0)+'  +  ('+FMT(a0-b0)+')  =  '+FMT(a0),
             17, '#ffffff', 'start');

  return s;
}

// ---- main render ----
function render(){
  var L = layout();
  var s = '';

  s += brackets(L.ax, L.ay, L.aw, L.ah, '#39ff6e');
  s += drawMatrixCells(A, L.ax, L.ay, M, K, L.STEP, '#39ff6e', 'A');
  s += label(L.ax + L.aw/2, L.ay - 28, 'A', 28, '#39ff6e');
  s += label(L.ax + L.aw/2, L.ay + L.ah + 38, M+'\u00D7'+K, 15, '#1f7a3d');

  s += label(L.mulX, L.mulY, '\u00D7', 56, '#1f7a3d');

  s += brackets(L.bx, L.by, L.bw, L.bh, '#ffd23f');
  s += drawMatrixCells(B, L.bx, L.by, K, N, L.STEP, '#ffd23f', 'B');
  s += label(L.bx + L.bw/2, L.by - 28, 'B', 28, '#ffd23f');
  s += label(L.bx + L.bw/2, L.by + L.bh + 38, K+'\u00D7'+N, 15, '#1f7a3d');

  s += label(L.eqX, L.eqY, '=', 56, '#1f7a3d');

  s += brackets(L.cx, L.cy, L.cw, L.ch, '#4fc3ff');
  s += drawMatrixCells(C, L.cx, L.cy, M, N, L.STEP, '#4fc3ff', 'C');
  s += label(L.cx + L.cw/2, L.cy - 28, 'C', 28, '#4fc3ff');
  s += label(L.cx + L.cw/2, L.cy + L.ch + 38, M+'\u00D7'+N, 15, '#1f7a3d');

  if(curOp){
    s += hlTile(L.ax, L.ay, L.STEP, curOp.ti, curOp.tk, '#ffffff');
    s += hlTile(L.bx, L.by, L.STEP, curOp.tk, curOp.tj, '#ffffff');
    s += hlTile(L.cx, L.cy, L.STEP, curOp.ti, curOp.tj, '#ffffff');
  }

  var wbY = L.bottom + 70;
  if(wbY > 820) wbY = 820;
  s += drawWorkbench(wbY);

  // ---- 3D LANDSCAPE OVERLAY (appended) ----
  if(V3.open){ s += v3_render(); }

  $('scene').innerHTML = s;
}

// ---- HUD ----
function renderHUD(){
  var s = '';
  s += label(60, 50, 'MMA TILE ENGINE', 30, '#39ff6e', 'start');
  s += label(60, 76, 'D = A\u00B7B + C on 4\u00D74 tiles   //   single SVG file   //   pure JS',
             14, '#1f7a3d', 'start');

  var btns = [
    { id: 's4',  l: '4\u00D74' },
    { id: 's8',  l: '8\u00D78' },
    { id: 's12', l: '12\u00D712' },
    { id: 'sq',  l: 'NON-SQ' },
    { id: 'rnd', l: 'RANDOM' },
    { id: 'idt', l: 'IDENTITY' },
    { id: 'pl',  l: cursor.running ? 'PAUSE' : (cursor.done ? 'REPLAY' : 'PLAY') },
    { id: 'st',  l: 'STEP' },
    { id: 'rs',  l: 'RESET' },
    { id: 'f16', l: FP16 ? 'FP16: ON' : 'FP16: OFF' },
    { id: 'v3',  l: V3.open ? '3D: ON' : '3D VIEW' }
  ];

  var bw = 132, bh = 38, gap = 10;
  var bx = 60, by = 110;
  for(var i = 0; i < btns.length; i++){
    var b = btns[i];
    var x = bx + i*(bw+gap);
    var active = (b.id === preset) || (b.id === 'f16' && FP16) || (b.id === 'v3' && V3.open);
    s += '<rect x="'+x+'" y="'+by+'" width="'+bw+'" height="'+bh+
         '" fill="'+(active?'#0d2a18':'#000')+
         '" stroke="'+(active?'#39ff6e':'#1f7a3d')+
         '" stroke-width="2" data-act="'+b.id+'" style="cursor:pointer"/>';
    s += label(x + bw/2, by + bh/2 + 6, b.l, 16, active ? '#39ff6e' : '#b6ffd0');
  }

  s += label(1860, 50,  'CLICK A CELL TO EDIT', 14, '#1f7a3d', 'end');
  s += label(1860, 72,  'DIGITS  .  -  BACKSPACE  ENTER  ARROWS', 13, '#1f7a3d', 'end');

  var status = cursor.done ? 'COMPLETE' : (cursor.running ? 'RUNNING' : (curOp ? 'STEPPED' : 'IDLE'));
  s += label(1860, 110, 'STATUS: ' + status, 14, '#39ff6e', 'end');
  var steps = cursor.ti*(N/T)*(K/T) + cursor.tj*(K/T) + cursor.tk;
  var total = (M/T)*(N/T)*(K/T);
  s += label(1860, 132, 'TILE: ' + steps + ' / ' + total, 14, '#1f7a3d', 'end');

  $('hud').innerHTML = s;
}

// ---- input ----
function findAct(el){
  while(el && el !== document){
    if(el.getAttribute){
      var a = el.getAttribute('data-act');
      if(a) return a;
    }
    el = el.parentNode;
  }
  return null;
}

function handleAct(a){
  switch(a){
    case 's4':  setSize(4,4,4,'s4'); break;
    case 's8':  setSize(8,8,8,'s8'); break;
    case 's12': setSize(12,12,12,'s12'); break;
    case 'sq':  setSize(8,12,8,'sq'); break;
    case 'rnd': randomize(); break;
    case 'idt': identity(); break;
    case 'pl':  togglePlay(); break;
    case 'st':  stepOnce(); break;
    case 'rs':  resetAnim(); computeC(); dirty = true; hudDirty = true; break;
    case 'f16': FP16 = !FP16; resetAnim(); computeC(); dirty = true; hudDirty = true; break;
    case 'v3':
      V3.open = !V3.open;
      if(V3.open){
        V3.autoSpin = true;
        V3.dist = v3_defaultDist();
        V3.yaw = 0.6;
        V3.pit = 0.38;
      }
      dirty = true; hudDirty = true; break;
  }
}

$('hud').addEventListener('pointerdown', function(e){
  var a = findAct(e.target);
  if(a) handleAct(a);
});

$('scene').addEventListener('pointerdown', function(e){
  var t = e.target;
  if(!t.getAttribute) return;
  var m = t.getAttribute('data-m');
  if(!m) return;
  if(cursor.running || cursor.done) return;
  if(sel) commitEdit();
  var i = parseInt(t.getAttribute('data-i'), 10);
  var j = parseInt(t.getAttribute('data-j'), 10);
  sel = { m: m, i: i, j: j };
  editBuf = String(m === 'A' ? A[i][j] : B[i][j]);
  freshEdit = true;
  dirty = true;
});

function commitEdit(){
  if(!sel || editBuf === null) return;
  var v = parseFloat(editBuf);
  if(!isFinite(v)) v = 0;
  v = f32(v);
  if(sel.m === 'A') A[sel.i][sel.j] = v;
  else               B[sel.i][sel.j] = v;
  resetAnim(); computeC();
  dirty = true; hudDirty = true;
}

window.addEventListener('keydown', function(e){
  if(!sel) return;
  var k = e.key;
  if(k === 'Escape'){ commitEdit(); sel = null; editBuf = null; dirty = true; return; }
  if(k === 'Enter'){  commitEdit(); sel = null; editBuf = null; dirty = true; return; }
  if(k === 'Backspace'){
    e.preventDefault();
    if(editBuf && editBuf.length > 0) editBuf = editBuf.slice(0, -1);
    if(!editBuf || editBuf === '-' || editBuf === '.') editBuf = '0';
    freshEdit = false; dirty = true; return;
  }
  if(k === 'ArrowLeft' || k === 'ArrowRight' || k === 'ArrowUp' || k === 'ArrowDown'){
    e.preventDefault();
    commitEdit();
    var di = 0, dj = 0;
    if(k === 'ArrowLeft')  dj = -1;
    if(k === 'ArrowRight') dj = 1;
    if(k === 'ArrowUp')    di = -1;
    if(k === 'ArrowDown')  di = 1;
    var rows = sel.m === 'A' ? M : K;
    var cols = sel.m === 'A' ? K : N;
    sel.i = (sel.i + di + rows) % rows;
    sel.j = (sel.j + dj + cols) % cols;
    editBuf = String(sel.m === 'A' ? A[sel.i][sel.j] : B[sel.i][sel.j]);
    freshEdit = true; dirty = true; return;
  }
  if(/^[0-9]$/.test(k) || k === '-' || k === '.'){
    e.preventDefault();
    if(freshEdit){
      if(k === '-')      editBuf = '-';
      else if(k === '.') editBuf = '0.';
      else               editBuf = k;
      freshEdit = false;
    } else {
      if(k === '-' && editBuf.indexOf('-') >= 0) return;
      if(k === '.' && editBuf.indexOf('.') >= 0) return;
      editBuf += k;
    }
    dirty = true; return;
  }
});

window.addEventListener('blur', function(){
  if(sel){ commitEdit(); sel = null; editBuf = null; }
});

// ---- loop ----
var lastT = 0;
function loop(ts){
  requestAnimationFrame(loop);
  var dt = Math.min(0.05, (ts - lastT)/1000 || 0.016);
  lastT = ts;
  if(cursor.running){
    cursor.t += dt;
    if(cursor.t >= cursor.speed){
      cursor.t = 0;
      step();
    }
  }
  // 3D auto-spin
  if(V3.open && V3.autoSpin && !V3.drag){
    V3.yaw += dt * 0.28;
    dirty = true;
  }
  if(hudDirty){ renderHUD(); hudDirty = false; }
  if(dirty){ render(); dirty = false; }
}

// ============================================================
// 3D LANDSCAPE VIEW  (appended, non-invasive)
//   Renders the LIVE C matrix as a heightfield:
//   x = column, z = row, y = value.
//   During animation the active tile is overlaid with the
//   accumulator so the surface builds smoothly, step by step.
//   Modes: MESH (filled quads), DOTS (spheres), BOTH, FLAT
//   Drag to orbit, scroll to zoom, ESC to close, 'r' to reset
// ============================================================

var V3 = {
  open: false,
  mode: 'mesh',
  yaw: 0.6,
  pit: 0.38,
  dist: 12,
  focus: 1400,
  drag: null,
  autoSpin: true
};

// Default camera distance proportional to matrix size
function v3_defaultDist(){
  var dim = Math.max(M, N);
  return 5 + dim * 1.2;
}

function v3_proj(p){
  var cx = 960, cy = 520;
  var dx = p[0], dy = p[1], dz = p[2];
  var cyaw = Math.cos(V3.yaw), syaw = Math.sin(V3.yaw);
  var x1 = dx*cyaw - dz*syaw;
  var z1 = dx*syaw + dz*cyaw;
  var cp = Math.cos(V3.pit), sp = Math.sin(V3.pit);
  var y2 = dy*cp + z1*sp;
  var z2 = -dy*sp + z1*cp;
  var d = z2 + V3.dist;
  if(d < 0.6) d = 0.6;
  return [cx + x1*V3.focus/d, cy - y2*V3.focus/d, d];
}

function v3_color(v, maxAbs){
  var t = Math.max(-1, Math.min(1, v / maxAbs));
  var r, g, b;
  if(t >= 0){
    r = 30 + Math.round(30 * t);
    g = 100 + Math.round(155 * t);
    b = 50 + Math.round(40 * t);
  } else {
    var at = -t;
    r = 100 + Math.round(155 * at);
    g = 30 + Math.round(30 * at);
    b = 50 + Math.round(40 * at);
  }
  return 'rgb(' + r + ',' + g + ',' + b + ')';
}

// Merge completed C with the in-progress accumulator at the active tile
function v3_liveMatrix(){
  var live = clone2D(C);
  if(curOp && accum){
    var ti = curOp.ti, tj = curOp.tj;
    for(var i = 0; i < T; i++){
      for(var j = 0; j < T; j++){
        var ri = ti*T + i, rj = tj*T + j;
        if(ri < M && rj < N) live[ri][rj] = curOp.after[i][j];
      }
    }
  }
  return live;
}

function v3_buildData(){
  var maxAbs = refMaxAbs;              // stable reference scale
  var live = v3_liveMatrix();
  var dim = Math.max(M, N);
  var spacing = dim <= 4 ? 2 : (dim <= 8 ? 1.4 : 1.0);
  var heightScale = 4.5 / maxAbs;
  var cx = (N-1)/2, cz = (M-1)/2;
  var pts = [];
  for(var i = 0; i < M; i++){
    pts[i] = [];
    for(var j = 0; j < N; j++){
      var v = live[i][j];
      var x = (j - cx) * spacing;
      var z = (i - cz) * spacing;
      var y = v * heightScale;
      pts[i][j] = { p: [x, y, z], v: v, i: i, j: j };
    }
  }
  return { pts: pts, maxAbs: maxAbs, spacing: spacing, cx: cx, cz: cz };
}

function v3_lineStr(pts3, color, w, op){
  var d = '';
  for(var i = 0; i < pts3.length; i++){
    var sp = v3_proj(pts3[i]);
    d += (i === 0 ? 'M' : 'L') + sp[0].toFixed(1) + ',' + sp[1].toFixed(1);
  }
  return '<path d="' + d + '" fill="none" stroke="' + color +
         '" stroke-width="' + w + '" stroke-opacity="' + op + '"/>';
}

function v3_render(){
  if(!V3.open) return '';
  var s = '';

  s += '<rect x="0" y="0" width="1920" height="1080" fill="#000" fill-opacity="0.9"/>';

  s += label(60, 46, '// C MATRIX \u2014 3D LANDSCAPE', 22, '#39ff6e', 'start');
  s += label(60, 72, M + ' \u00D7 ' + N + ' cells   \u2022   height = value   \u2022   ' +
             'drag = orbit   \u2022   scroll = zoom   \u2022   R = reset view   \u2022   ESC = close',
             13, '#1f7a3d', 'start');

  // Status readout (fix #3: status visible inside the 3D overlay)
  var status = cursor.done ? 'COMPLETE' : (cursor.running ? 'RUNNING' : (curOp ? 'STEPPED' : 'IDLE'));
  var stepsDone = cursor.ti*(N/T)*(K/T) + cursor.tj*(K/T) + cursor.tk;
  var stepsTotal = (M/T)*(N/T)*(K/T);
  s += label(960, 96,
    'STATUS: ' + status + '   TILE: ' + stepsDone + ' / ' + stepsTotal +
    '   FP16: ' + (FP16 ? 'ON' : 'OFF') +
    '   max|C| = ' + FMT(refMaxAbs),
    15, '#39ff6e', 'middle');

  var modes = [
    { id: 'mesh', l: 'MESH' },
    { id: 'dots', l: 'DOTS' },
    { id: 'both', l: 'BOTH' },
    { id: 'flat', l: 'FLAT' }
  ];
  var mbw = 100, mbh = 32, mbx = 1180, mby = 30, mg = 8;
  for(var mi = 0; mi < modes.length; mi++){
    var mx = mbx + mi * (mbw + mg);
    var act = V3.mode === modes[mi].id;
    s += '<rect x="' + mx + '" y="' + mby + '" width="' + mbw + '" height="' + mbh +
         '" fill="' + (act ? '#0d2a18' : '#000') + '" stroke="' + (act ? '#39ff6e' : '#1f7a3d') +
         '" stroke-width="2" data-v3mode="' + modes[mi].id + '" style="cursor:pointer"/>';
    s += label(mx + mbw/2, mby + mbh/2 + 6, modes[mi].l, 15, act ? '#39ff6e' : '#b6ffd0');
  }

  s += '<rect x="1800" y="30" width="100" height="32" fill="#000" stroke="#ff4444" ' +
       'stroke-width="2" data-v3close="1" style="cursor:pointer"/>';
  s += label(1850, 52, 'CLOSE', 15, '#ff4444');

  var data = v3_buildData();
  var pts = data.pts;
  var maxAbs = data.maxAbs;
  var spacing = data.spacing;
  var vcx = data.cx, vcz = data.cz;

  var DL = [];

  // ground grid at y=0
  for(var i = 0; i < M; i++){
    var linePts = [];
    for(var j = 0; j < N; j++){
      linePts.push([(j - vcx) * spacing, 0, (i - vcz) * spacing]);
    }
    DL.push({ z: 50000 + i, s: v3_lineStr(linePts, '#0f3d1e', 1, 0.55) });
  }
  for(var j2 = 0; j2 < N; j2++){
    var linePts2 = [];
    for(var i2 = 0; i2 < M; i2++){
      linePts2.push([(j2 - vcx) * spacing, 0, (i2 - vcz) * spacing]);
    }
    DL.push({ z: 50000 + j2 + 0.5, s: v3_lineStr(linePts2, '#0f3d1e', 1, 0.55) });
  }

  // Active tile highlight (dashed wireframe on the ground plane)
  if(curOp && accum && !cursor.done){
    var ati = curOp.ti, atj = curOp.tj;
    var tx0 = (atj*T - vcx) * spacing - spacing/2;
    var tx1 = ((atj*T + T - 1) - vcx) * spacing + spacing/2;
    var tz0 = (ati*T - vcz) * spacing - spacing/2;
    var tz1 = ((ati*T + T - 1) - vcz) * spacing + spacing/2;
    var c0 = v3_proj([tx0, 0.01, tz0]);
    var c1 = v3_proj([tx1, 0.01, tz0]);
    var c2 = v3_proj([tx1, 0.01, tz1]);
    var c3 = v3_proj([tx0, 0.01, tz1]);
    var boxZ = (c0[2] + c1[2] + c2[2] + c3[2]) / 4 - 0.1;
    var dstr = 'M' + c0[0].toFixed(1) + ',' + c0[1].toFixed(1) +
               'L' + c1[0].toFixed(1) + ',' + c1[1].toFixed(1) +
               'L' + c2[0].toFixed(1) + ',' + c2[1].toFixed(1) +
               'L' + c3[0].toFixed(1) + ',' + c3[1].toFixed(1) + 'Z';
    DL.push({
      z: boxZ,
      s: '<path d="' + dstr + '" fill="none" stroke="#ffffff" ' +
         'stroke-width="2" stroke-dasharray="5,4" stroke-opacity="0.85"/>'
    });
  }

  // vertical drop lines from each peak to the floor
  for(var i = 0; i < M; i++){
    for(var j = 0; j < N; j++){
      var pt = pts[i][j];
      if(Math.abs(pt.p[1]) < 0.01) continue;
      var s0 = v3_proj(pt.p);
      var s1 = v3_proj([pt.p[0], 0, pt.p[2]]);
      var col = v3_color(pt.v, maxAbs);
      DL.push({
        z: (s0[2] + s1[2]) / 2 + 0.4,
        s: '<line x1="' + s0[0].toFixed(1) + '" y1="' + s0[1].toFixed(1) +
           '" x2="' + s1[0].toFixed(1) + '" y2="' + s1[1].toFixed(1) +
           '" stroke="' + col + '" stroke-width="1" stroke-opacity="0.32"/>'
      });
    }
  }

  // filled mesh quads
  if(V3.mode === 'mesh' || V3.mode === 'both'){
    for(var i = 0; i < M - 1; i++){
      for(var j = 0; j < N - 1; j++){
        var p00 = pts[i][j].p;
        var p01 = pts[i][j+1].p;
        var p10 = pts[i+1][j].p;
        var p11 = pts[i+1][j+1].p;
        var s00 = v3_proj(p00);
        var s01 = v3_proj(p01);
        var s10 = v3_proj(p10);
        var s11 = v3_proj(p11);
        var avgZ = (s00[2] + s01[2] + s10[2] + s11[2]) / 4;
        var avgV = (pts[i][j].v + pts[i][j+1].v + pts[i+1][j].v + pts[i+1][j+1].v) / 4;
        var col = v3_color(avgV, maxAbs);
        var dstr = 'M' + s00[0].toFixed(1) + ',' + s00[1].toFixed(1) +
                   'L' + s01[0].toFixed(1) + ',' + s01[1].toFixed(1) +
                   'L' + s11[0].toFixed(1) + ',' + s11[1].toFixed(1) +
                   'L' + s10[0].toFixed(1) + ',' + s10[1].toFixed(1) + 'Z';
        DL.push({
          z: avgZ,
          s: '<path d="' + dstr + '" fill="' + col + '" fill-opacity="0.55" ' +
             'stroke="' + col + '" stroke-width="1.4" stroke-opacity="0.95" ' +
             'stroke-linejoin="round"/>'
        });
      }
    }
  }

  // dots at each cell
  if(V3.mode === 'dots' || V3.mode === 'both' || V3.mode === 'flat'){
    for(var i = 0; i < M; i++){
      for(var j = 0; j < N; j++){
        var pt2 = pts[i][j];
        var scr = v3_proj(pt2.p);
        var col2 = v3_color(pt2.v, maxAbs);
        var mag = Math.abs(pt2.v) / maxAbs;
        var r = (3 + 5 * mag) * (14 / scr[2]);
        if(r < 2) r = 2;
        if(r > 22) r = 22;
        DL.push({
          z: scr[2] - 0.02,
          s: '<circle cx="' + scr[0].toFixed(1) + '" cy="' + scr[1].toFixed(1) +
             '" r="' + r.toFixed(1) + '" fill="' + col2 +
             '" stroke="#000" stroke-width="1.2"/>'
        });
      }
    }
  }

  DL.sort(function(a, b){ return b.z - a.z; });
  for(var d2 = 0; d2 < DL.length; d2++) s += DL[d2].s;

  // legend with numeric bounds from refMaxAbs
  var legendY = 1000;
  s += label(60, legendY, 'C[i][j]:', 15, '#1f7a3d', 'start');
  for(var lg = 0; lg < 8; lg++){
    var lv = (lg / 7) * 2 - 1;
    var lc = v3_color(lv * maxAbs, maxAbs);
    s += '<rect x="' + (140 + lg * 26) + '" y="' + (legendY - 14) +
         '" width="26" height="18" fill="' + lc + '" stroke="#1f7a3d" stroke-width="1"/>';
  }
  s += label(140, legendY + 30, '-' + FMT(maxAbs), 11, '#1f7a3d', 'start');
  s += label(231, legendY + 30, '0', 11, '#1f7a3d', 'middle');
  s += label(322, legendY + 30, '+' + FMT(maxAbs), 11, '#1f7a3d', 'end');

  s += label(1860, 1000, 'max|C| = ' + FMT(maxAbs), 14, '#4fc3ff', 'end');
  s += label(1860, 1024, 'mode: ' + V3.mode + '   autospin: ' + (V3.autoSpin ? 'on' : 'off'),
             13, '#1f7a3d', 'end');

  return s;
}

function v3_inScene(el){
  while(el){
    if(el.id === 'scene') return true;
    if(el === document || el === document.body) return false;
    el = el.parentNode;
  }
  return false;
}

function v3_handlePointer(e){
  var t = e.target;
  if(!t || !t.getAttribute) return;
  var modeAttr = t.getAttribute('data-v3mode');
  if(modeAttr){ V3.mode = modeAttr; dirty = true; hudDirty = true; return; }
  var closeAttr = t.getAttribute('data-v3close');
  if(closeAttr){ V3.open = false; V3.autoSpin = true; dirty = true; hudDirty = true; return; }
  V3.drag = { x: e.clientX, y: e.clientY };
  V3.autoSpin = false;
  dirty = true; hudDirty = true;
}

document.addEventListener('pointerdown', function(e){
  if(!V3.open) return;
  if(!v3_inScene(e.target)) return;
  e.stopPropagation();
  e.preventDefault();
  v3_handlePointer(e);
}, true);

window.addEventListener('pointermove', function(e){
  if(!V3.drag) return;
  var dx = e.clientX - V3.drag.x;
  var dy = e.clientY - V3.drag.y;
  V3.yaw += dx * 0.008;
  V3.pit += dy * 0.006;
  if(V3.pit > 1.5) V3.pit = 1.5;
  if(V3.pit < -0.15) V3.pit = -0.15;
  V3.drag.x = e.clientX;
  V3.drag.y = e.clientY;
  dirty = true;
});

window.addEventListener('pointerup', function(){
  if(V3.drag){ V3.drag = null; }
});

window.addEventListener('wheel', function(e){
  if(!V3.open) return;
  e.preventDefault();
  V3.dist += e.deltaY * 0.015;
  if(V3.dist < 4) V3.dist = 4;
  if(V3.dist > 60) V3.dist = 60;
  dirty = true;
}, { passive: false });

window.addEventListener('keydown', function(e){
  if(!V3.open) return;
  if(e.key === 'Escape'){
    V3.open = false; V3.autoSpin = true;
    dirty = true; hudDirty = true;
    e.preventDefault(); e.stopImmediatePropagation(); return;
  }
  if(e.key === 'r' || e.key === 'R'){
    V3.yaw = 0.6; V3.pit = 0.38;
    V3.dist = v3_defaultDist();          // reset to fitted distance
    V3.autoSpin = true;
    dirty = true; hudDirty = true;
    e.preventDefault(); e.stopImmediatePropagation(); return;
  }
  e.preventDefault(); e.stopImmediatePropagation();
}, true);

// ============================================================
// boot
// ============================================================
setSize(4, 4, 4, 's4');
requestAnimationFrame(loop);
